import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel b8bd735:
# &packet.RequestAbility{Ability: 19, Value: float32(0.5)}
FLOAT = bytes.fromhex("2602000000003f")

# generated by gophertunnel b8bd735:
# &packet.RequestAbility{Ability: 9, Value: true}
BOOL = bytes.fromhex("12010100000000")

# generated by gophertunnel b8bd735:
# &packet.RequestAbility{Ability: -1, Value: false}
INVALID = bytes.fromhex("01010000000000")

GOLDENS = [
    pytest.param(
        v2168.RequestAbilityPacket(
            ability=v2168.AbilitiesIndex.VERTICAL_FLY_SPEED,
            value_type=v2168.RequestAbilityPacket.Type.FLOAT,
            bool_=False,
            float_=0.5,
        ),
        FLOAT,
        id="float",
    ),
    pytest.param(
        v2168.RequestAbilityPacket(
            ability=v2168.AbilitiesIndex.FLYING,
            value_type=v2168.RequestAbilityPacket.Type.BOOL,
            bool_=True,
            float_=0.0,
        ),
        BOOL,
        id="bool-with-four-float-bytes",
    ),
    pytest.param(
        v2168.RequestAbilityPacket(
            ability=v2168.AbilitiesIndex.INVALID,
            value_type=v2168.RequestAbilityPacket.Type.BOOL,
            bool_=False,
            float_=0.0,
        ),
        INVALID,
        id="invalid-ability-as-a-zigzag-varint",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_request_ability_is_packet_184(version):
    assert version.PACKETS[184] is version.RequestAbilityPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_request_ability_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_request_ability_decodes_from_its_golden(packet, golden):
    assert v2168.RequestAbilityPacket.from_bytes(golden) == packet
